mapper.select:
SELECT s.id AS seat_id, c.coach_no, s.seat_no, s.seat_letter
FROM train_seat s
JOIN train_coach c ON c.id = s.coach_id
JOIN seat_segment_inventory i ON i.seat_id = s.id AND i.run_id = #{runId}
AND i.segment_seq >= #{fromSeq} AND i.segment_seq < #{toSeq}
WHERE c.seat_type_id = #{seatTypeId}
GROUP BY s.id, c.coach_no, s.seat_no, s.seat_letter
HAVING COUNT(*) = #{toSeq} - #{fromSeq}
AND SUM(i.status = 'AVAILABLE') = #{toSeq} - #{fromSeq}
ORDER BY CASE
WHEN #{seatPreference} = 'WINDOW' AND s.seat_letter IN ('A', 'F') THEN 0
WHEN #{seatPreference} = 'AISLE' AND s.seat_letter IN ('C', 'D') THEN 0
ELSE 1 END, c.coach_no, s.seat_no
LIMIT #{limit}

SELECT id, segment_seq, status, order_item_id
FROM seat_segment_inventory
WHERE run_id = #{runId} AND seat_id = #{seatId}
AND segment_seq >= #{fromSeq} AND segment_seq < #{toSeq}
ORDER BY segment_seq
FOR UPDATE

mapper.update:
UPDATE seat_segment_inventory
SET status = 'LOCKED', order_item_id = #{orderItemId}, lock_expire_at = #{expireAt},
version = version + 1, updated_at = NOW()
WHERE run_id = #{runId} AND seat_id = #{seatId}
AND segment_seq >= #{fromSeq} AND segment_seq < #{toSeq}
AND status = 'AVAILABLE'
